import '@dev.hiconic/gm_root-model';
import '@dev.hiconic/gm_selector-model';
import '@dev.hiconic/gm_i18n-model';
import '@dev.hiconic/gm_gm-core-api';

import { T } from '@dev.hiconic/hc-js-base';

export declare namespace meta {
	const groupId: string;
	const artifactId: string;
	const version: string;
}

export import ExplicitPredicate = T.com.braintribe.model.meta.data.ExplicitPredicate;
export import HasMetaData = T.com.braintribe.model.meta.data.HasMetaData;
export import MetaData = T.com.braintribe.model.meta.data.MetaData;
export import MetaDataSelector = T.com.braintribe.model.meta.selector.MetaDataSelector;
export import ModelSkeletonCompatible = T.com.braintribe.model.meta.data.ModelSkeletonCompatible;
export import Predicate = T.com.braintribe.model.meta.data.Predicate;
export import PredicateErasure = T.com.braintribe.model.meta.data.PredicateErasure;
export import UniversalMetaData = T.com.braintribe.model.meta.data.UniversalMetaData;

declare module '@dev.hiconic/hc-js-base' {

	namespace T.com.braintribe.model.meta.data {

		const ExplicitPredicate: hc.reflection.EntityType<ExplicitPredicate>;
		type ExplicitPredicate = Predicate &
		  Entity<"com.braintribe.model.meta.data.ExplicitPredicate">;

		const HasMetaData: hc.reflection.EntityType<HasMetaData>;
		type HasMetaData = T.com.braintribe.model.generic.GenericEntity &
		  Entity<"com.braintribe.model.meta.data.HasMetaData", {
			metaData: set<MetaData>;
		}>;

		const MetaData: hc.reflection.EntityType<MetaData>;
		type MetaData = T.com.braintribe.model.generic.GenericEntity &
		  Entity<"com.braintribe.model.meta.data.MetaData", {
			conflictPriority: double;
			important: P<boolean, { nullable: false }>;
			inherited: P<boolean, { nullable: false }>;
			selector: T.com.braintribe.model.meta.selector.MetaDataSelector;
		}>;

		const ModelSkeletonCompatible: hc.reflection.EntityType<ModelSkeletonCompatible>;
		type ModelSkeletonCompatible = T.com.braintribe.model.generic.GenericEntity &
		  Entity<"com.braintribe.model.meta.data.ModelSkeletonCompatible">;

		const Predicate: hc.reflection.EntityType<Predicate>;
		type Predicate = MetaData &
		  Entity<"com.braintribe.model.meta.data.Predicate">;

		const PredicateErasure: hc.reflection.EntityType<PredicateErasure>;
		type PredicateErasure = Predicate &
		  Entity<"com.braintribe.model.meta.data.PredicateErasure">;

		const UniversalMetaData: hc.reflection.EntityType<UniversalMetaData>;
		type UniversalMetaData = MetaData &
		  Entity<"com.braintribe.model.meta.data.UniversalMetaData">;

	}

	namespace T.com.braintribe.model.meta.selector {

		const MetaDataSelector: hc.reflection.EntityType<MetaDataSelector>;
		type MetaDataSelector = T.com.braintribe.model.selector.Selector &
		  Entity<"com.braintribe.model.meta.selector.MetaDataSelector">;

	}

}
